def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    output = [[background] * cols for _ in range(rows)]
    seen = set()
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < rows and 0 <= nx < cols and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            top = min(y for y, x in cells) + 1
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells) + 1
            right = max(x for y, x in cells)
            for y in range(top, bottom):
                for x in range(left, right):
                    output[y][x] = color
    return output
